function Get-WsmObservationClock { [DateTimeOffset]::UtcNow }
function Assert-WsmObservationHours($Value) {
    if($Value -isnot [int] -and $Value -isnot [long]){throw 'ObservationHours must be an integer.'}
    if($Value -lt 1 -or $Value -gt 8760){throw 'ObservationHours must be between 1 and 8760.'}
}
function Get-WsmObservationWindow($State) {
    if(-not $State.Cutover -or $State.Cutover.Stage -cne 'Activated' -or -not $State.Cutover.PSObject.Properties['ActivatedUtc'] -or -not $State.Cutover.PSObject.Properties['ObservationHours']){throw 'Observation requires a durable completed activation and reviewed duration.'}
    Assert-WsmObservationHours $State.Cutover.ObservationHours
    $activation=[DateTimeOffset]::MinValue
    if(-not [DateTimeOffset]::TryParse($State.Cutover.ActivatedUtc,[ref]$activation) -or $activation.Offset -ne [TimeSpan]::Zero){throw 'Invalid activation UTC timestamp.'}
    $now=Get-WsmObservationClock
    if($activation -gt $now){throw 'Clock precedes completed activation; observation is blocked.'}
    $earliest=$activation.AddHours($State.Cutover.ObservationHours)
    [pscustomobject]@{ActivatedUtc=$State.Cutover.ActivatedUtc;RequiredHours=$State.Cutover.ObservationHours;EarliestCompletionUtc=$earliest.ToString('o');ObservedUntilUtc=$now.ToString('o');ElapsedHours=($now-$activation).TotalHours;Ready=($now -ge $earliest);BusinessEvidenceRequired=$true}
}
function Complete-WsmCutoverObservation($Paths,$State) {
    Assert-WsmObservationHours $State.Cutover.ObservationHours
    $activation=Get-WsmUtc
    $State.Cutover | Add-Member NoteProperty ActivatedUtc $activation -Force
    Add-WsmJournal $Paths $State 'CutoverCompleted' '' ([pscustomobject]@{Status=$State.Stage;ActivatedUtc=$activation;ObservationHours=$State.Cutover.ObservationHours})
}
function Get-WsmExternalReadinessEvidencePhase([string]$Check) {
    switch -CaseSensitive ($Check) {
        SourceOwnershipRestored { return 'SourceResumeReady' }
        {$_ -in @('SourceIdentityReleased','SourceWritersFenced','TargetIsolationConfirmed','ExternalNetworkFencing','NetworkOwnerApproval')} { return 'CutoverReady' }
        ManualRestore { return 'StagedDependencyVerified' }
        BusinessStaged { return 'CutoverReady' }
        RollbackReconcile { return 'RollbackReady' }
        {$_ -in @('BackupRestore','LongCycleJobs','Observation','RetirementRetention','ExternalConsumerOldPathDrained','SpecialProductDisposition','DataRetentionHandoff','CredentialHandoff','CertificateHandoff','CMDBHandoff','DNSHandoff','LicenseHandoff','MonitoringHandoff','RollbackCutoffAndDeletionOwner')} { return 'RetirementReady' }
        default { return 'FinalAccepted' }
    }
}
function Get-WsmExternalReadinessFacts([string]$Check) {
    $map=@{
        ManualRestore=@('NativeReadbackPerformed','ExpectedStateMatched','OwnerAccepted')
        BusinessStaged=@('ConsumerExecuted','ExpectedResultMatched','OwnerAccepted')
        BusinessFinal=@('ConsumerExecuted','ExpectedResultMatched','OwnerAccepted')
        DNS=@('ForwardResolutionMatched','ReverseResolutionMatched','OwnerAccepted')
        Kerberos=@('TicketObtained','ServicePrincipalMatched','OwnerAccepted')
        ExternalConnectivity=@('EndpointReachable','ExpectedIdentityMatched','OwnerAccepted')
        Monitoring=@('SignalObserved','AlertRouteConfirmed','OwnerAccepted')
        BackupRestore=@('BackupRestored','IntegrityVerified','OwnerAccepted')
        LongCycleJobs=@('LongCycleRunCompleted','ResultVerified','OwnerAccepted')
        SecurityAgent=@('AgentHealthy','PolicyConfirmed','OwnerAccepted')
        License=@('EntitlementVerified','UsageWithinTerms','OwnerAccepted')
        UserAcceptance=@('UserWorkflowPassed','OwnerAccepted')
        Observation=@('WindowCompleted','AlertReviewPassed','OwnerAccepted')
        RetirementRetention=@('RetentionTermRecorded','OwnerAccepted')
        RollbackReconcile=@('WritersStopped','LatestTargetPreserved','DataReconciled','ProductSynchronizationComplete','OwnerAccepted')
        SourceIdentityReleased=@('HostnameReleased','IpReleased','DomainIdentityReleased','OwnerAccepted')
        SourceWritersFenced=@('SourceWritersStopped','ExternalWritersFenced','OwnerAccepted')
        TargetIsolationConfirmed=@('TargetIsolated','TemporaryIdentityVerified','OwnerAccepted')
        ExternalNetworkFencing=@('DnsPtrFenced','SpnFenced','DhcpFenced','LoadBalancerFenced','OwnerAccepted')
        NetworkOwnerApproval=@('FinalNameApproved','FinalIpApproved','DnsApproved','RollbackProcedureApproved','OwnerAccepted')
        ExternalConsumerOldPathDrained=@('OldPathTrafficZero','ObservationWindowComplete','OwnerAccepted')
        SpecialProductDisposition=@('ProductOwnerDispositionComplete','VendorProcedureComplete','OwnerAccepted')
        DataRetentionHandoff=@('RetentionTermRecorded','DataOwnerAccepted','OwnerAccepted')
        CredentialHandoff=@('CredentialOwnersUpdated','OldCredentialsRevoked','OwnerAccepted')
        CertificateHandoff=@('CertificateOwnersUpdated','OldCertificatesRevoked','OwnerAccepted')
        CMDBHandoff=@('CIRelationshipsUpdated','OwnerAccepted')
        DNSHandoff=@('OldRecordsRetired','NewRecordsOwned','OwnerAccepted')
        LicenseHandoff=@('LicenseTransferred','OldEntitlementReleased','OwnerAccepted')
        MonitoringHandoff=@('MonitoringOwnerUpdated','AlertRouteTested','OwnerAccepted')
        RollbackCutoffAndDeletionOwner=@('RollbackDeadlineRecorded','IrrevocablePointRecorded','DeletionOwnerAuthorized','OwnerAccepted')
        SourceOwnershipRestored=@('TargetWritersStopped','LatestTargetPreserved','ReconciliationCompleted','SourceExclusiveWriteOwner','OwnerAccepted')
    }
    if(-not $map.ContainsKey($Check)){throw ('Unsupported external readiness check: '+$Check)}
    @($map[$Check])
}
function Assert-WsmLocalExternalEvidenceFile([string]$Path,[long]$MaximumBytes) {
    if([string]::IsNullOrWhiteSpace($Path) -or $Path -notmatch '^[A-Za-z]:\\'){throw 'External evidence files must be local drive paths; UNC and drive-relative paths are rejected.'}
    if($Path.Substring(2).Contains(':')){throw 'External evidence paths cannot address alternate data streams.'};$full=[IO.Path]::GetFullPath($Path);Assert-WsmNoReparse $full
    if(-not [IO.File]::Exists($full)){throw 'External evidence file is absent.'}
    $info=New-Object IO.FileInfo($full);if($info.Length -lt 1 -or $info.Length -gt $MaximumBytes){throw 'External evidence file exceeds its bounded size limit.'}
    $full
}function Assert-WsmExternalReadinessEvidence {
    param([Parameter(Mandatory)][string]$Path,[Parameter(Mandatory)][string]$SHA256,[Parameter(Mandatory)]$Package,[Parameter(Mandatory)][string]$Check,[string]$ItemId='')
