    Assert-WsmEnvelope $e 'ExternalReadinessEvidence'
    Assert-WsmFields $e @('SchemaVersion','ToolVersion','Kind','EvidenceId','PairId','SourceFingerprint','TargetFingerprint','ToolFingerprint','PlanHash','ManifestHash','Phase','Check','ItemId','Context','Owner','ObservedUtc','ExpiresUtc','PayloadArtifact','TypedResults','FreezeEpoch','SourceWriterInventory','WriterSetHash','SourceAttemptHash','SourceAttemptId') @('EvidenceId','PairId','SourceFingerprint','TargetFingerprint','ToolFingerprint','PlanHash','ManifestHash','Phase','Check','ItemId','Context','Owner','ObservedUtc','ExpiresUtc','PayloadArtifact','TypedResults')
    if($e.SchemaVersion -ne 1 -or $e.ToolVersion -cne $script:ToolVersion){throw 'External readiness evidence schema/tool version is unsupported.'}
    Assert-WsmId $e.EvidenceId
    if($e.PairId -cne $Package.Manifest.PairId -or $e.SourceFingerprint -ine $Package.Manifest.Source.Fingerprint -or $e.TargetFingerprint -ine $Package.Manifest.Target.Fingerprint -or $e.ToolFingerprint -ine $Package.Plan.ToolFingerprint -or $e.PlanHash -ine $Package.Manifest.PlanHash -or $e.ManifestHash -ine $Package.SHA256){throw 'External readiness evidence is bound to a different pair, source, target, tool, plan or manifest.'}
    $phase=Get-WsmExternalReadinessEvidencePhase $Check
