    if($sourceFreeze){$phase='SourceFreezeReady'}
    $sourceResume=($Check -ceq 'SourceOwnershipRestored' -and $e.Phase -ceq 'SourceResumeReady');if($sourceResume){$phase='SourceResumeReady'}
    if($e.Check -cne $Check -or $e.Phase -cne $phase -or $e.ItemId -cne $ItemId){throw 'External readiness evidence check, item or phase does not match the requested gate.'}
    if([string]::IsNullOrWhiteSpace([string]$e.Owner) -or $e.Owner.Length -gt 256 -or $e.Owner -match '[\x00-\x1f]|(?i)(password|passwd|secret|token|credential|private[ _-]?key)[\s:=]'){throw 'External evidence requires a bounded non-secret owner identifier.'}
    Assert-WsmFields $e.Context @('Scope','ItemId','ContextType','ConsumerId','Provider','Version','Architecture','RuntimeAccount','AccountType','AccountSid','ServiceName','Endpoint','OracleHome','ObservedEffectivePath','ConsumerItemIds','WindowId','CIRelationshipId','RetentionPolicyId') @('Scope','ItemId','ContextType','ConsumerId')
    if($e.Context.Scope -cnotin @('Item','Pair') -or $e.Context.ContextType -cnotin @('Consumer','Cutover','Rollback','Retirement','Acceptance','Preparation')){throw 'External evidence context scope/type is not supported.'}
    foreach($property in $e.Context.PSObject.Properties){if($property.Name -ceq 'ConsumerItemIds'){if(@($property.Value).Count -gt 100 -or @($property.Value | Where-Object {$_ -isnot [string] -or $_.Length -gt 256 -or $_ -match '(?i)(password|passwd|secret|token|credential|private[ _-]?key)[\s:=]'}).Count){throw 'External evidence consumer list exceeds its bound or includes a secret-like value.'}}else{$contextValue=$property.Value;if($contextValue -isnot [string] -or $contextValue.Length -gt 512 -or $contextValue -match '[\x00-\x1f]|(?i)(password|passwd|secret|token|credential|private[ _-]?key)[\s:=]'){$valueType='null';if($null -ne $contextValue){$valueType=$contextValue.GetType().FullName};throw ('External evidence context field is not a bounded non-secret string: '+$property.Name+' ('+$valueType+')')}}}
    if($ItemId){if($e.Context.Scope -cne 'Item' -or -not $e.Context.PSObject.Properties['ItemId'] -or $e.Context.ItemId -cne $ItemId){throw 'Item-level external evidence context is not bound to the selected consumer.'}}
    elseif($e.Context.Scope -cne 'Pair' -or ($e.Context.PSObject.Properties['ItemId'] -and $e.Context.ItemId)){throw 'Pair-level external evidence must use an exact pair context.'}
    $observed=ConvertTo-WsmQualificationUtc ([string]$e.ObservedUtc) ObservedUtc;$expires=ConvertTo-WsmQualificationUtc ([string]$e.ExpiresUtc) ExpiresUtc;$now=[DateTimeOffset]::UtcNow
    if($observed -gt $now.AddMinutes(5) -or $expires -le $now -or $expires -le $observed -or ($expires-$observed).TotalHours -gt 720){throw 'External readiness evidence is expired or has an invalid time interval.'}
    Assert-WsmFields $e.PayloadArtifact @('Path','SHA256') @('Path','SHA256')
    if([string]$e.PayloadArtifact.SHA256 -notmatch '^[a-fA-F0-9]{64}$'){throw 'External evidence requires an absolute, hash-bound payload artifact.'}
    $artifact=Assert-WsmLocalExternalEvidenceFile ([string]$e.PayloadArtifact.Path) 128MB
    if((Get-FileHash -LiteralPath $artifact -Algorithm SHA256).Hash -ine [string]$e.PayloadArtifact.SHA256){throw 'External evidence payload artifact is absent or changed.'}
    $facts=Get-WsmExternalReadinessFacts $Check;if($sourceFreeze){$facts=@('WriterSetEnumerated','WriterOwnershipReviewed','AllWritersStopped','OwnerAccepted')};$result=$e.TypedResults
    Assert-WsmFields $result @('Outcome','TestId','Method','Expected','Observed','Facts','NotApplicableReasons') @('Outcome','TestId','Method','Expected','Observed','Facts')
    foreach($field in @('TestId','Method','Expected','Observed')){$value=[string]$result.$field;if([string]::IsNullOrWhiteSpace($value) -or $value.Length -gt 1024 -or $value -match '[\x00-\x08\x0b\x0c\x0e-\x1f]|(?i)(password|passwd|secret|token|credential|private[ _-]?key)[\s:=]'){throw ('External typed result is missing or has an invalid/secret-like '+$field+'.')}}
    if([string]$result.TestId -notmatch '^[A-Za-z0-9_.:-]{1,128}$' -or [string]$result.Method -cnotin @('NativeReadback','BusinessTransaction','OwnerObservation','DirectoryReadback','NetworkReadback','BackupRestore','MonitoringReview','RetirementReview','Reconciliation','HumanProcedure','FixtureMock')){throw 'External typed result TestId or Method is not a supported finite value.'}
    if($result.Outcome -cnotin @('Pass','Fail')){throw 'External typed result Outcome must be Pass or Fail.'}
    $factNames=@($result.Facts.PSObject.Properties.Name);if(@($facts | Where-Object {$factNames -cnotcontains $_}).Count -or @($factNames | Where-Object {$facts -cnotcontains $_}).Count){throw 'External typed result facts do not exactly match this check.'}
    $notApplicable=@();$failed=$false
    $notApplicableAllowed=@('DomainIdentityReleased','DhcpFenced','LoadBalancerFenced','SpnFenced','DnsPtrFenced')
    foreach($fact in $facts){$value=$result.Facts.$fact;if($value -is [bool]){if(-not $value){$failed=$true}}elseif($value -ceq 'NotApplicable'){if($notApplicableAllowed -cnotcontains $fact){throw ('NotApplicable is prohibited for safety-critical fact: '+$fact)};$notApplicable+=@($fact)}else{throw ('External typed fact must be Boolean or NotApplicable: '+$fact)}}
    $reasons=@{};if($result.PSObject.Properties['NotApplicableReasons']){foreach($property in $result.NotApplicableReasons.PSObject.Properties){$reasons[$property.Name]=[string]$property.Value}}
    if(@($notApplicable | Where-Object {$reasons[$_] -notmatch '.{10,}' }).Count){throw 'Each NotApplicable fact requires a specific owner reason of at least 10 characters.'}
    if(@($reasons.Keys | Where-Object {$notApplicable -cnotcontains $_}).Count){throw 'NotApplicable reason names a fact that was not marked NotApplicable.'}
    if($result.Facts.OwnerAccepted -isnot [bool] -or -not $result.Facts.OwnerAccepted){throw 'External owner acceptance must be an explicit Boolean true.'}
    if($sourceFreeze){
        if(-not $e.PSObject.Properties['FreezeEpoch'] -or [string]$e.FreezeEpoch -notmatch '^[0-9a-fA-F-]{36}$' -or -not $e.PSObject.Properties['SourceWriterInventory'] -or -not $e.PSObject.Properties['WriterSetHash']){throw 'SourceFreezeReady evidence requires an epoch and a bounded writer inventory.'}
