        $writerIds=@{};$canonical=New-Object 'System.Collections.Generic.List[object]'
        foreach($writer in $writers){Assert-WsmFields $writer @('WriterId','Owner','Scope','Kind','Stopped','OwnershipReviewed','EvidenceId') @('WriterId','Owner','Scope','Kind','Stopped','OwnershipReviewed','EvidenceId');foreach($field in @('WriterId','Owner','Scope','Kind','EvidenceId')){$value=[string]$writer.$field;if([string]::IsNullOrWhiteSpace($value) -or $value.Length -gt 256 -or $value -match '[\x00-\x1f]'){throw 'Source writer inventory contains an invalid bounded identifier.'}};if($writerIds.ContainsKey([string]$writer.WriterId) -or $writer.Stopped -isnot [bool] -or $writer.OwnershipReviewed -isnot [bool] -or -not $writer.Stopped -or -not $writer.OwnershipReviewed){throw 'Every enumerated source writer must be uniquely identified, stopped, and ownership-reviewed.'};$writerIds[[string]$writer.WriterId]=$true;$canonical.Add([pscustomobject][ordered]@{WriterId=[string]$writer.WriterId;Owner=[string]$writer.Owner;Scope=[string]$writer.Scope;Kind=[string]$writer.Kind;Stopped=[bool]$writer.Stopped;OwnershipReviewed=[bool]$writer.OwnershipReviewed;EvidenceId=[string]$writer.EvidenceId})}
        if([string]$e.WriterSetHash -notmatch '^[a-fA-F0-9]{64}$'){throw 'Source writer inventory requires a SHA256 projection hash.'};$writerJson=ConvertTo-Json -InputObject @($canonical.ToArray()) -Depth 8 -Compress;$actualWriterHash=[Security.Cryptography.SHA256]::Create();try{$writerBytes=[Text.Encoding]::UTF8.GetBytes($writerJson);$computedWriterHash=([BitConverter]::ToString($actualWriterHash.ComputeHash($writerBytes))).Replace('-','')}finally{$actualWriterHash.Dispose()};if($computedWriterHash -ine [string]$e.WriterSetHash){throw 'Source writer inventory projection hash mismatch.'}
        if($result.Facts.WriterSetEnumerated -isnot [bool] -or -not $result.Facts.WriterSetEnumerated -or $result.Facts.WriterOwnershipReviewed -isnot [bool] -or -not $result.Facts.WriterOwnershipReviewed -or $result.Facts.AllWritersStopped -isnot [bool] -or -not $result.Facts.AllWritersStopped){throw 'SourceFreezeReady typed results do not prove complete writer enumeration, ownership review, and stop state.'}
    }
