    [pscustomobject]@{Evidence=$e;Path=[IO.Path]::GetFullPath($Path);SHA256=$SHA256.ToLowerInvariant();Passed=($computed -eq 'Pass');Phase=$phase;Check=$Check;ItemId=$ItemId;Owner=[string]$e.Owner;Context=$e.Context}
