function Assert-WsmExternalReadinessReferences {
    param([object[]]$References,[Parameter(Mandatory)]$Package,[Parameter(Mandatory)][string[]]$RequiredChecks)
    if(@($References).Count -gt 100){throw 'External readiness reference count exceeds its bound.'}
    $validated=New-Object 'System.Collections.Generic.List[object]';$byCheck=@{}
    foreach($reference in @($References)){
        Assert-WsmFields $reference @('Path','SHA256','Check','ItemId','Phase','EvidenceId','Owner','Passed') @('Path','SHA256','Check')
        $itemId='';if($reference.PSObject.Properties['ItemId']){$itemId=[string]$reference.ItemId}
        $evidence=Assert-WsmExternalReadinessEvidence -Path ([string]$reference.Path) -SHA256 ([string]$reference.SHA256) -Package $Package -Check ([string]$reference.Check) -ItemId $itemId
        foreach($field in @('Phase','EvidenceId','Owner','Passed')){if($reference.PSObject.Properties[$field] -and [string]$reference.$field -cne [string]$(switch($field){Phase{$evidence.Phase};EvidenceId{$evidence.Evidence.EvidenceId};Owner{$evidence.Owner};Passed{$evidence.Passed}})){throw ('External readiness reference '+$field+' projection changed: '+$reference.Check)}}
        if($byCheck.ContainsKey($evidence.Check)){throw ('Duplicate external readiness evidence check: '+$evidence.Check)};$byCheck[$evidence.Check]=$true
        $validated.Add([pscustomobject][ordered]@{Path=$evidence.Path;SHA256=$evidence.SHA256;Check=$evidence.Check;ItemId=$itemId;Phase=$evidence.Phase;EvidenceId=$evidence.Evidence.EvidenceId;Owner=$evidence.Owner;Passed=$evidence.Passed})
    }
    $missing=@($RequiredChecks | Where-Object {-not $byCheck.ContainsKey($_)});if($missing.Count){throw ('Required external readiness evidence is missing: '+($missing -join ', '))}
    foreach($check in $RequiredChecks){$row=@($validated | Where-Object Check -ceq $check)[0];if(-not $row.Passed){throw ('External readiness evidence did not pass: '+$check)}}
    $validated.ToArray()
}
function Assert-WsmSourceFreezeEvidence([string]$Path,[string]$SHA256,$Plan,[string]$PlanHash,[string]$FreezeEpoch) {
    $surrogate=[pscustomobject]@{Manifest=[pscustomobject]@{PairId=$Plan.PairId;Source=[pscustomobject]@{Fingerprint=$Plan.Source.Fingerprint};Target=[pscustomobject]@{Fingerprint=$Plan.Target.Fingerprint};PlanHash=$PlanHash};Plan=[pscustomobject]@{ToolFingerprint=$Plan.ToolFingerprint};SHA256=''}
    $proof=Assert-WsmExternalReadinessEvidence -Path $Path -SHA256 $SHA256 -Package $surrogate -Check SourceWritersFenced -ItemId ''
    if($proof.Phase -cne 'SourceFreezeReady' -or $proof.Evidence.ManifestHash -cne '' -or $proof.Evidence.FreezeEpoch -cne $FreezeEpoch){throw 'SourceFreezeReady evidence must bind the exact plan, tool, pair, source, target and freeze epoch with no future manifest hash.'}
    [pscustomobject]@{EvidenceId=$proof.Evidence.EvidenceId;SHA256=$proof.SHA256;Owner=$proof.Owner;WriterSetHash=[string]$proof.Evidence.WriterSetHash;FreezeEpoch=$FreezeEpoch;PairId=$Plan.PairId;SourceFingerprint=$Plan.Source.Fingerprint;TargetFingerprint=$Plan.Target.Fingerprint;ToolFingerprint=$Plan.ToolFingerprint;PlanHash=$PlanHash;Phase='SourceFreezeReady';Check='SourceWritersFenced';ObservedUtc=$proof.Evidence.ObservedUtc;ExpiresUtc=$proof.Evidence.ExpiresUtc;Passed=$proof.Passed}
}
function Assert-WsmSourceFreezeEvidenceMatchesAttestation($Evidence,$Freeze) {
    foreach($field in @('EvidenceId','SHA256','Owner','WriterSetHash','FreezeEpoch','PairId','SourceFingerprint','TargetFingerprint','ToolFingerprint','PlanHash','Phase','Check','ObservedUtc','ExpiresUtc','Passed')){if([string]$Evidence.$field -cne [string]$Freeze.SourceFreezeEvidence.$field){throw ('SourceFreezeReady proof changed from the transferred freeze attestation: '+$field)}}
}
function Assert-WsmSourceResumeEvidence([string]$Path,[string]$SHA256,$Plan,[string]$PlanHash,$Attempt,[string]$AttemptHash,[string]$Owner) {
    $surrogate=[pscustomobject]@{Manifest=[pscustomobject]@{PairId=$Plan.PairId;Source=[pscustomobject]@{Fingerprint=$Plan.Source.Fingerprint};Target=[pscustomobject]@{Fingerprint=$Plan.Target.Fingerprint};PlanHash=$PlanHash};Plan=[pscustomobject]@{ToolFingerprint=$Plan.ToolFingerprint};SHA256=''}
    $proof=Assert-WsmExternalReadinessEvidence -Path $Path -SHA256 $SHA256 -Package $surrogate -Check SourceOwnershipRestored -ItemId ''
    if($proof.Phase -cne 'SourceResumeReady' -or $proof.Evidence.ManifestHash -cne '' -or $proof.Evidence.SourceAttemptHash -ine $AttemptHash -or $proof.Evidence.SourceAttemptId -cne $Attempt.State.AttemptId -or $proof.Owner -cne $Owner){throw 'SourceResumeReady evidence is not bound to this exact source attempt and responsible owner.'}
    [pscustomobject]@{EvidenceId=$proof.Evidence.EvidenceId;SHA256=$proof.SHA256;Owner=$proof.Owner;PairId=$Plan.PairId;SourceFingerprint=$Plan.Source.Fingerprint;TargetFingerprint=$Plan.Target.Fingerprint;ToolFingerprint=$Plan.ToolFingerprint;PlanHash=$PlanHash;SourceAttemptHash=$AttemptHash;SourceAttemptId=[string]$Attempt.State.AttemptId;Phase='SourceResumeReady';Check='SourceOwnershipRestored';ObservedUtc=$proof.Evidence.ObservedUtc;ExpiresUtc=$proof.Evidence.ExpiresUtc;Passed=$proof.Passed}
}
function Assert-WsmFreezeAttestation($Freeze,$Plan,[string]$ExpectedPlanHash,[switch]$AllowExpired) {
    if(-not $Freeze.PSObject.Properties['SourceFreezeEvidence']){throw 'Freeze is missing typed SourceFreezeReady fencing evidence.'};$a=$Freeze.SourceFreezeEvidence
    Assert-WsmFields $a @('EvidenceId','SHA256','Owner','WriterSetHash','FreezeEpoch','PairId','SourceFingerprint','TargetFingerprint','ToolFingerprint','PlanHash','Phase','Check','ObservedUtc','ExpiresUtc','Passed') @('EvidenceId','SHA256','Owner','WriterSetHash','FreezeEpoch','PairId','SourceFingerprint','TargetFingerprint','ToolFingerprint','PlanHash','Phase','Check','ObservedUtc','ExpiresUtc','Passed')
    if($a.PairId -cne $Plan.PairId -or $a.SourceFingerprint -ine $Plan.Source.Fingerprint -or $a.TargetFingerprint -ine $Plan.Target.Fingerprint -or $a.ToolFingerprint -ine $Plan.ToolFingerprint -or $a.ToolFingerprint -notmatch '^[a-fA-F0-9]{64}$' -or $a.PlanHash -ine $ExpectedPlanHash -or $Freeze.PlanHash -ine $ExpectedPlanHash -or $a.FreezeEpoch -cne $Freeze.FreezeEpoch -or $a.Owner -cne $Freeze.Owner -or [string]::IsNullOrWhiteSpace([string]$a.Owner) -or $a.Phase -cne 'SourceFreezeReady' -or $a.Check -cne 'SourceWritersFenced' -or $a.Passed -isnot [bool] -or -not $a.Passed -or $a.SHA256 -notmatch '^[a-fA-F0-9]{64}$' -or $a.WriterSetHash -notmatch '^[a-fA-F0-9]{64}$'){throw 'Freeze SourceFreezeReady attestation binding is invalid.'}
    $observed=ConvertTo-WsmQualificationUtc ([string]$a.ObservedUtc) SourceFreezeObservedUtc;$expires=ConvertTo-WsmQualificationUtc ([string]$a.ExpiresUtc) SourceFreezeExpiresUtc;$now=[DateTimeOffset]::UtcNow
    if($observed -gt $now.AddMinutes(5) -or (-not $AllowExpired -and $expires -le $now) -or $expires -le $observed -or ($expires-$observed).TotalHours -gt 720){throw 'SourceFreezeReady attestation expired or has invalid UTC bounds.'}
    $a
}
function Invoke-WsmFreezeCore {
    [CmdletBinding(SupportsShouldProcess)]param([string]$PlanPath,[string]$ExpectedHash,[string]$Path,[string]$Owner,[string]$Evidence,[Parameter(Mandatory)][string]$Acknowledgement,[switch]$SourceIdentityReleased,[string]$ReleaseEvidence,[ValidateRange(1,48)][int]$ValidHours=4,[Parameter(Mandatory)][string]$SourceStateDirectory,[string]$PreviousFreezePath,[string]$PreviousFreezeHash,[string]$SourceAttemptPath,[string]$OriginalBaselinePath,[string]$OriginalBaselineHash,[string]$FreezeExternalEvidencePath,[string]$FreezeExternalEvidenceHash,[string]$FreezeEpoch)
    $p=Read-WsmMigrationPlan $PlanPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $p.Source.Fingerprint
    if($Acknowledgement -cne 'OWNER-CONFIRMED-QUIESCENCE' -or -not $Owner -or -not $Evidence){throw 'Source freeze requires owner-confirmed quiescence and independent evidence.'}
    if(-not $FreezeExternalEvidencePath -or -not $FreezeExternalEvidenceHash){throw 'A SourceFreezeReady typed external writer fence is required before the final package can be frozen.'};if(-not $FreezeEpoch){$FreezeEpoch=[Guid]::NewGuid().ToString()};$sourceFreezeEvidence=Assert-WsmSourceFreezeEvidence $FreezeExternalEvidencePath $FreezeExternalEvidenceHash $p $ExpectedHash $FreezeEpoch;if($sourceFreezeEvidence.Owner -cne $Owner){throw 'SourceFreezeReady owner differs from freeze owner.'}
    if($SourceIdentityReleased -and -not $ReleaseEvidence){throw 'Source hostname/IP/domain release requires independent release evidence.'}
    $previousFreeze=$null;if($PreviousFreezePath){$previousFreeze=Read-WsmFreezeRecord $PreviousFreezePath $PreviousFreezeHash $p $ExpectedHash -AllowExpired}
    $beforeResult=Export-WsmInventory $SourceStateDirectory -DeepDiscovery:($p.Source.PSObject.Properties['DiscoveryDepth'] -and $p.Source.DiscoveryDepth -eq 'Deep');$before=Read-WsmTrustedJson $beforeResult.Path $beforeResult.SHA256;$original=@{};foreach($i in $before.Items){$original[$i.ItemId]=$i};if($before.Source.HostId -cne $p.Source.HostId){throw 'Source inventory identity mismatch.'};foreach($i in $p.Items){if($i.Decision -eq 'Include' -and $i.Kind -ne 'ManualItem'){$baseline=$i.SettingsHash;if($previousFreeze){$old=@($previousFreeze.QuiescedSettingsHashes | Where-Object ItemId -CEQ $i.ItemId);if($old.Count -ne 1 -or $old[0].OriginalHash -cne $i.SettingsHash){throw 'Previous freeze baseline does not match approved item.'};$baseline=$old[0].QuiescedHash};if(-not $original.ContainsKey($i.ItemId) -or $original[$i.ItemId].SettingsHash -cne $baseline){throw 'Source configuration drift before freeze; review required.'}}}
    if(-not $PSCmdlet.ShouldProcess($p.Source.Name,'Disable selected source producers and record owner-confirmed freeze')){return}
