    $freezeOrder=@(Get-WsmRestoreOrder @($p.Items | Where-Object Decision -EQ Include));[array]::Reverse($freezeOrder)
    foreach($i in $freezeOrder){$allowed=@{ScheduledTask='ScheduledTask';Service='Service';IISPool='IISPool';IISSite='IISSite'};if($allowed.ContainsKey($i.Kind) -and $i.MigrationSpec.Adapter -cne $allowed[$i.Kind]){$activities.Add([pscustomobject]@{ItemId=$i.ItemId;Kind=$i.Kind;State='OwnerConfirmedDedicatedQuiescence';Name=$i.NaturalKey});continue};switch($i.Kind){
        Share {if($i.MigrationSpec.Adapter -eq 'SmbShare'){if(-not $SourceAttemptPath){throw 'Share drain needs durable source freeze workflow baseline.'};$attempt=Read-WsmJson $SourceAttemptPath;$shareBaseline=@($attempt.ShareBaselines | Where-Object ItemId -CEQ $i.ItemId);if($shareBaseline.Count -ne 1){throw 'Share has no unique saved original ACL baseline.'};$drain=Invoke-WsmShareQuiescence -Plan $p -Item $i -BaselinePath $shareBaseline[0].Path -BaselineHash $shareBaseline[0].SHA256 -AttemptPath $SourceAttemptPath -AttemptHash (Get-FileHash -LiteralPath $SourceAttemptPath).Hash;$activities.Add($drain.Activity)}else{$activities.Add([pscustomobject]@{ItemId=$i.ItemId;Kind='Share';State='OwnerConfirmedDedicatedQuiescence';Name=$i.NaturalKey})}}
        ScheduledTask {$full=$i.NaturalKey;$last=$full.LastIndexOf('\');$folder=$full.Substring(0,$last+1);$name=$full.Substring($last+1);Disable-ScheduledTask -TaskName $name -TaskPath $folder | Out-Null;$t=Get-ScheduledTask -TaskName $name -TaskPath $folder;if($t.Settings.Enabled -or [string]$t.State -eq 'Running'){throw 'Task is enabled/running; stop/reconcile its in-flight business operation before freezing.'};$activities.Add([pscustomobject]@{ItemId=$i.ItemId;Kind='ScheduledTask';State='Disabled';Name=$full})}
        Service {$name=$i.NaturalKey;Set-Service -Name $name -StartupType Disabled;Stop-Service -Name $name -ErrorAction Stop;$s=Get-CimInstance Win32_Service | Where-Object Name -CEQ $name;if(-not $s -or $s.StartMode -ne 'Disabled' -or $s.State -ne 'Stopped'){throw 'Source service did not quiesce.'};$activities.Add([pscustomobject]@{ItemId=$i.ItemId;Kind='Service';State='DisabledStopped';Name=$name})}
        {$_ -in @('IISSite','IISPool')} {$m=New-WsmIisManager;try{$o=$m.Sites[$i.NaturalKey];if($i.Kind -eq 'IISPool'){$o=$m.ApplicationPools[$i.NaturalKey];$o.AutoStart=$false}else{$o.ServerAutoStart=$false};if(-not $o){throw 'Source IIS object absent.'};$m.CommitChanges();if([string]$o.State -ne 'Stopped'){[void]$o.Stop()};if([string]$o.State -ne 'Stopped'){throw 'Source IIS object did not stop.'};$activities.Add([pscustomobject]@{ItemId=$i.ItemId;Kind=$i.Kind;State='Stopped';Name=$i.NaturalKey})}finally{$m.Dispose()}}
