function Test-WsmEvidence($State,[string]$ItemId,[string]$Check,[string]$ManifestHash) {
    $matches=New-Object 'System.Collections.Generic.List[object]';foreach($candidate in @($State.Evidence)){if($candidate.ItemId -cne $ItemId -or $candidate.Check -cne $Check -or -not $candidate.Passed -or $candidate.ManifestHash -ine $ManifestHash){continue};try{$expiry=ConvertTo-WsmQualificationUtc ([string]$candidate.ExpiresUtc) EvidenceExpiresUtc;if($expiry -gt [DateTimeOffset]::UtcNow){$matches.Add($candidate)}}catch{}}
