    try{$ref=$record.ExternalEvidence;if($ref.PairId -cne $State.PairId -or $ref.TargetFingerprint -cne $State.TargetFingerprint -or $ref.PlanHash -ine $State.PlanHash -or $ref.ManifestHash -ine $ManifestHash -or $ref.Check -cne $Check -or $ref.ItemId -cne $ItemId){return $false};$surrogate=[pscustomobject]@{Manifest=[pscustomobject]@{PairId=$State.PairId;Source=[pscustomobject]@{Fingerprint=$ref.SourceFingerprint};Target=[pscustomobject]@{Fingerprint=$State.TargetFingerprint};PlanHash=$State.PlanHash};Plan=[pscustomobject]@{ToolFingerprint=$ref.ToolFingerprint};SHA256=$ManifestHash};$verified=Assert-WsmExternalReadinessEvidence -Path $ref.Path -SHA256 $ref.SHA256 -Package $surrogate -Check $Check -ItemId $ItemId;if($verified.Evidence.EvidenceId -cne $ref.EvidenceId -or -not $verified.Passed){return $false}}catch{return $false}
