        Write-WsmJson (Join-Path $paths.Root ('validation-'+$Phase+'.json')) $result;Add-WsmJournal $paths $state 'ValidationCompleted' '' ([pscustomobject]@{Phase=$Phase;Passed=$passed;Checks=$checks.Count});$result
