    Write-WsmJson $Path $p;[pscustomobject]@{Path=[IO.Path]::GetFullPath($Path);SHA256=(Get-FileHash -LiteralPath $Path).Hash;Plan=$p}
}
function Invoke-WsmAdapterActivation($Spec,[bool]$Enable,$Ownership=$null) {
    if($Spec.Adapter -in @('FileScope','ManualWorkflow')){return}
    $d=$Spec.Desired;$desired='Disabled';if($Spec.PSObject.Properties['DesiredFinalState']){$desired=$Spec.DesiredFinalState};$active=$Enable -and $desired -in @('Enabled','Automatic','Manual','Running')
    switch($Spec.Adapter){
        WindowsFeature {if($Ownership -and $Ownership.CreatedByTool){Invoke-WsmInstallerConsumerActivation $d $Ownership.InstallerSafety $Enable}}
        ScheduledTask {if($active){Enable-ScheduledTask -TaskName $d.TaskName -TaskPath $d.TaskPath | Out-Null}else{Disable-ScheduledTask -TaskName $d.TaskName -TaskPath $d.TaskPath | Out-Null}}
        Service {if($active){$accountPolicy=Get-WsmServiceAccountPolicy $d $Spec;if($accountPolicy.Mode -ceq 'ManagedServiceAccount'){[void](Test-WsmServiceAccountTargetPreflight $accountPolicy)};Set-WsmServiceSupplement $d.Name $d.Supplement -Phase Final | Out-Null;$mode='Manual';if($desired -eq 'Automatic'){$mode='Automatic'};Set-Service -Name $d.Name -StartupType $mode;if($desired -in @('Automatic','Running')){Start-Service -Name $d.Name}}else{Set-Service -Name $d.Name -StartupType Disabled;Stop-Service -Name $d.Name -ErrorAction Stop;Set-WsmServiceSupplement $d.Name $d.Supplement -Phase Staged | Out-Null}}
        SmbShare {if($active){if(-not (Test-WsmDesiredWorldDeny $d)){Unblock-SmbShareAccess -Name $d.Name -ScopeName '*' -AccountName (Get-WsmEveryoneName) -Force | Out-Null}}else{Block-SmbShareAccess -Name $d.Name -ScopeName '*' -AccountName (Get-WsmEveryoneName) -Force | Out-Null}}
        LocalUser {if($active){Enable-LocalUser -Name $d.Name}else{Disable-LocalUser -Name $d.Name}}
        FirewallRule {if($active){Enable-NetFirewallRule -Name $d.Name}else{Disable-NetFirewallRule -Name $d.Name}}
        {$_ -in @('IISSite','IISPool')} {$m=New-WsmIisManager;try{$o=$m.Sites[$d.Name];if($Spec.Adapter -eq 'IISPool'){$o=$m.ApplicationPools[$d.Name];$o.AutoStart=$active;$xml=Read-WsmXml $d.Xml;$mode='OnDemand';if($active -and $xml.DocumentElement.HasAttribute('startMode')){$mode=$xml.DocumentElement.GetAttribute('startMode')};$o.StartMode=[Enum]::Parse([Microsoft.Web.Administration.StartMode],$mode,$true)}else{$o.ServerAutoStart=$active};$m.CommitChanges();if($active){[void]$o.Start()}elseif([string]$o.State -ne 'Stopped'){[void]$o.Stop()}}finally{$m.Dispose()}}
    }
}
function Invoke-WsmCutover {
    [CmdletBinding(SupportsShouldProcess)]param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory,[string]$CutoverPlanPath,[string]$CutoverPlanHash,[string]$Acknowledgement,[hashtable]$Secrets=@{},[switch]$ResumeActivation,[string]$ResumeOwner,[string]$ResumeEvidence,[object[]]$GeneralHostEvidence=@(),[object[]]$ExternalEvidenceReferences=@())
