    $now=[DateTime]::UtcNow;if($now -lt [DateTime]::Parse($plan.Network.MaintenanceWindowUtc).ToUniversalTime() -or $now -ge [DateTime]::Parse($plan.Network.ValidUntilUtc).ToUniversalTime()){throw 'Outside approved cutover window.'};[void](Read-WsmFreezeRecord (Join-Path $package.Root 'freeze.json') $package.Manifest.FreezeHash $package.Plan $package.Manifest.PlanHash)
