    if(-not $PSCmdlet.ShouldProcess($package.Manifest.PairId,'Apply reviewed isolated pilot identity/network and activation')){return [pscustomobject]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='CutoverExecutionPreview';PairId=$package.Manifest.PairId;ManifestHash=$ExpectedHash;CutoverPlanHash=$CutoverPlanHash;Status='NotStarted';Executed=$false;PreflightValidated=$true;TargetStateRead=$false;TargetStateGatesEvaluated=$false;StagedValidationPassed=$null;NextStep='Review current target state and rerun without -WhatIf to evaluate staged gates and activate.';ProductionVerified=$false}}
