    if($existing.Cutover -and $existing.Cutover.NewTransactionsPossible){if($existing.Cutover.Stage -eq 'Activated'){return $existing};if(-not $ResumeActivation -or [string]::IsNullOrWhiteSpace($ResumeOwner) -or [string]::IsNullOrWhiteSpace($ResumeEvidence)){throw 'Interrupted activation requires explicit ResumeActivation, responsible owner and reconciliation evidence.'}}
    $resuming=($existing.Cutover -and $existing.Cutover.NewTransactionsPossible);if(-not $resuming){$validation=Invoke-WsmValidation $ManifestPath $ExpectedHash $StateDirectory Staged @{} $GeneralHostEvidence;if(-not $validation.Passed){throw 'Final-generation staging has drifted, dependencies are open, or business evidence is missing.'}}
