        if($resuming){Assert-WsmActivationNetwork $network;$review=[pscustomobject]@{Owner=$ResumeOwner;Evidence=$ResumeEvidence;Utc=(Get-WsmUtc);ManifestHash=$ExpectedHash;CutoverPlanHash=$CutoverPlanHash};$state.Cutover | Add-Member NoteProperty ResumeReview $review -Force;Add-WsmJournal $paths $state 'ActivationResumeReviewed' '' $review;Invoke-WsmCutoverSettingTransitions $package $paths $state;Invoke-WsmActivationSequence $package $paths $state -Resume;$state.Cutover.Stage='Activated';$state.Stage='PostCutoverValidationRequired';Complete-WsmCutoverObservation $paths $state;return $state};if($env:COMPUTERNAME -ine $network.FinalName){$args=@{NewName=$network.FinalName;Force=$true;ErrorAction='Stop'};if($Secrets.ContainsKey('DomainRename')){$args.DomainCredential=$Secrets.DomainRename};Rename-Computer @args | Out-Null;$state.Stage='RebootRequired';$state.Cutover.Stage='RenameRebootRequired';Add-WsmJournal $paths $state 'RenameRequiresReboot' '' ([pscustomobject]@{FinalName=$network.FinalName});return $state}
