        $state.Cutover.Stage='Activated';$state.Stage='PostCutoverValidationRequired';Complete-WsmCutoverObservation $paths $state;$state
    }
}
function Invoke-WsmCutoverSettingTransitions($Package,$Paths,$State) {
    foreach($item in @($Package.Plan.Items | Where-Object {$_.Decision -eq 'Include' -and $_.MigrationSpec.PSObject.Properties['SettingTransition'] -and $_.MigrationSpec.SettingTransition.RequiredPhase -eq 'CutoverReady'})) {
        [void](Invoke-WsmSettingTransitionForPhase $item $Package $Paths $State CutoverReady)
    }
}
function Get-WsmNetworkSnapshot {
    [pscustomobject]@{Name=$env:COMPUTERNAME;Addresses=@(Get-NetIPAddress | Select-Object InterfaceAlias,IPAddress,PrefixLength);DNS=@(Get-DnsClientServerAddress | Select-Object InterfaceAlias,ServerAddresses);Routes=@(Get-NetRoute | Select-Object InterfaceAlias,DestinationPrefix,NextHop)}
}
function Get-WsmAcceptanceGates {
    param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory,[object[]]$GeneralHostEvidence=@())
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;$paths=Get-WsmOperationPaths $StateDirectory $p.Manifest.PairId;$s=Get-WsmOperationState $paths $p;$missing=New-Object 'System.Collections.Generic.List[string]'
    if($s.ManifestHash -ine $ExpectedHash -or -not $p.Manifest.Final){$missing.Add('Applied final generation')};if(-not $s.Cutover -or $s.Cutover.Stage -ne 'Activated'){$missing.Add('Reviewed cutover activation')}
    $v=Invoke-WsmValidation $ManifestPath $ExpectedHash $StateDirectory Final @{} $GeneralHostEvidence;if(-not $v.Passed){$missing.Add('Final per-item configuration, dependency and business validation')}
    foreach($check in @('DNS','Kerberos','ExternalConnectivity','Monitoring','SecurityAgent','License','UserAcceptance')){if(-not (Test-WsmEvidence $s '' $check $ExpectedHash)){$missing.Add($check)}};$accepted=$missing.Count -eq 0
    $retirement=New-Object 'System.Collections.Generic.List[string]';foreach($check in @('BackupRestore','LongCycleJobs','Observation','RetirementRetention','ExternalConsumerOldPathDrained','SpecialProductDisposition','DataRetentionHandoff','CredentialHandoff','CertificateHandoff','CMDBHandoff','DNSHandoff','LicenseHandoff','MonitoringHandoff','RollbackCutoffAndDeletionOwner')){if(-not (Test-WsmEvidence $s '' $check $ExpectedHash)){$retirement.Add($check)}}
    $observation=$null;try{$observation=Get-WsmObservationWindow $s}catch{$observation=[pscustomobject]@{Ready=$false;Reason=$_.Exception.Message}}
    [pscustomobject]@{Observation=$observation;PairId=$s.PairId;FinalAccepted=$accepted;RetirementReady=($accepted -and $retirement.Count -eq 0);MissingFinal=$missing.ToArray();MissingRetirement=$retirement.ToArray();Mode='IsolatedPilot';ProductionVerified=$false;RetirementAction='Report only; never deletes source or secrets'}
}
function Export-WsmStageResult {
    param([string]$ManifestPath,[string]$ExpectedHash,[string]$StateDirectory,[ValidateSet('Restore','PreCutoverValidation','Cutover','PostCutoverValidation','Retirement')][string]$Stage,[string]$Path,[object[]]$GeneralHostEvidence=@())
    $p=Test-WsmMigrationPackage $ManifestPath $ExpectedHash;Assert-WsmMigrationHost (Get-WsmMachineIdentity) $p.Manifest.Target.Fingerprint;$paths=Get-WsmOperationPaths $StateDirectory $p.Manifest.PairId
    $gates=$null;if($Stage -in @('PostCutoverValidation','Retirement')){$gates=Get-WsmAcceptanceGates $ManifestPath $ExpectedHash $StateDirectory $GeneralHostEvidence}
    Invoke-WsmLocked $paths.Root {$s=Get-WsmOperationState $paths $p;if($s.ManifestHash -ine $ExpectedHash){$attemptMatches=($Stage -ceq 'Restore' -and $s.Stage -cin @('Failed','Cancelled','Running') -and $s.PSObject.Properties['RestoreAttempt'] -and $s.RestoreAttempt.ManifestHash -ieq $ExpectedHash -and $s.RestoreAttempt.Generation -eq $p.Manifest.Generation);if(-not $attemptMatches){throw 'No current applied generation or matching durable restore attempt.'}};$status='Blocked';switch($Stage){Restore{$status=$s.Stage;if($status -notin @('Succeeded','Failed','Cancelled','RebootRequired','ManualEvidenceRequired')){$status='Blocked'}};PreCutoverValidation{$pathV=Join-Path $paths.Root 'validation-Staged.json';if([IO.File]::Exists($pathV)){$v=Read-WsmJson $pathV;if($v.ManifestHash -ieq $ExpectedHash -and $v.Passed){$status='Succeeded'}}};Cutover{if($s.Cutover -and $s.Cutover.Stage -eq 'Activated'){$status='Succeeded'}};PostCutoverValidation{if($gates.FinalAccepted){$status='Succeeded'}else{$status='ManualEvidenceRequired'}};Retirement{if($gates.RetirementReady){$status='Succeeded'}else{$status='ManualEvidenceRequired'}}};$s.ResultSequence++;$r=[pscustomobject]@{SchemaVersion=1;ToolVersion=$script:ToolVersion;Kind='StageResult';BatchId=$p.Manifest.BatchId;PairId=$p.Manifest.PairId;SourceHostId=$p.Plan.Source.HostId;TargetHostId=$p.Plan.Target.HostId;TargetFingerprint=$p.Plan.Target.Fingerprint;InventoryRevision=$p.Manifest.InventoryRevision;DecisionRevision=$p.Manifest.DecisionRevision;ApprovalId=$p.Manifest.ApprovalId;PlanHash=$p.Manifest.PlanHash;ManifestHash=$ExpectedHash;PayloadGeneration=$p.Manifest.Generation;RunId=$s.RunId;Sequence=$s.ResultSequence;Stage=$Stage;Status=$status;ProducedUtc=(Get-WsmUtc);Mode='IsolatedPilot';ProductionVerified=$false;JournalHash=$s.JournalHash};Write-WsmJson $Path $r;Add-WsmJournal $paths $s 'StageResultExported' '' ([pscustomobject]@{Stage=$Stage;Sequence=$r.Sequence;Status=$status});[pscustomobject]@{Path=[IO.Path]::GetFullPath($Path);SHA256=(Get-FileHash -LiteralPath $Path).Hash;Result=$r}}
}
